DO $baseline$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'supabase_functions') THEN
    EXECUTE $trigger$CREATE TRIGGER "users-pending-review-notify" AFTER INSERT ON public.users_pending_review FOR EACH ROW EXECUTE FUNCTION supabase_functions.http_request('https://app.margenticos.com/api/webhooks/users-pending-review-notify', 'POST', '{"x-webhook-secret":"<REDACTED: set from SUPABASE_PENDING_REVIEW_WEBHOOK_SECRET>"}', '{}', '5000')$trigger$;
  ELSE
    RAISE WARNING 'SKIPPED a Database Webhook trigger: schema supabase_functions does not exist. Enable Database Webhooks in the Supabase dashboard, then re-run this statement and set its header value from SUPABASE_PENDING_REVIEW_WEBHOOK_SECRET.';
  END IF;
END
$baseline$;

